const btn = document.querySelector('button.pay');
const cs = getComputedStyle(btn);
const rect = btn.getBoundingClientRect();
let ancestors = [];
let el = btn.parentElement;
while (el) {
  const ecs = getComputedStyle(el);
  const erect = el.getBoundingClientRect();
  ancestors.push({tag: el.tagName, cls: el.className, overflow: ecs.overflow, height: ecs.height, maxHeight: ecs.maxHeight, rect: {h: erect.height, w: erect.width}});
  el = el.parentElement;
}
JSON.stringify({
  color: cs.color,
  backgroundColor: cs.backgroundColor,
  border: cs.border,
  rect,
  ancestors
}, null, 2);

